package com.readlearncode.constraints.positiveorzero;

import org.junit.BeforeClass;
import org.junit.Test;

import javax.validation.ConstraintViolation;
import javax.validation.Validation;
import javax.validation.Validator;
import java.math.BigDecimal;
import java.util.Set;
import java.util.concurrent.atomic.LongAdder;

import static org.assertj.core.api.Java6Assertions.assertThat;

/**
 * Source code github.com/readlearncode
 *
 * @author Alex Theedom www.readlearncode.com
 * @version 1.0
 */
public class NumbersTest {

    private static Validator validator;

    @BeforeClass
    public static void setUpValidator() {
        validator = Validation.buildDefaultValidatorFactory().getValidator();
    }

    @Test
    public void givenBeanWithPositiveFields_shouldValidate() {

        Numbers numbers = new Numbers();

        numbers.setABigDecimal(BigDecimal.TEN);
        numbers.setAPrimitiveNumber(5);

        LongAdder longAdder = new LongAdder();
        longAdder.add(5);
        numbers.setALongAdder(longAdder);

        Set<ConstraintViolation<Numbers>> constraintViolations = validator.validate(numbers);
        assertThat(constraintViolations.size()).isEqualTo(0);
    }

    @Test
    public void givenBeanWithZeroFields_shouldValidate() {
        Numbers numbers = new Numbers();

        numbers.setABigDecimal(BigDecimal.ZERO);
        numbers.setAPrimitiveNumber(0);

        LongAdder longAdder = new LongAdder();
        longAdder.add(0);
        numbers.setALongAdder(longAdder);

        Set<ConstraintViolation<Numbers>> constraintViolations = validator.validate(numbers);
        assertThat(constraintViolations.size()).isEqualTo(0);
    }

    @Test
    public void givenBeanWithNegativeFields_shouldNotValidate() {
        Numbers numbers = new Numbers();

        numbers.setABigDecimal(BigDecimal.valueOf(-1));
        numbers.setAPrimitiveNumber(-5);

        LongAdder longAdder = new LongAdder();
        longAdder.add(-5);
        numbers.setALongAdder(longAdder);

        Set<ConstraintViolation<Numbers>> constraintViolations = validator.validate(numbers);
        assertThat(constraintViolations.size()).isEqualTo(3);
    }

}

package com.technicalrex.webapp.pegger.api;

import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableMap;
import com.technicalrex.webapp.pegger.api.games.GameTools;

import javax.inject.Inject;
import javax.ws.rs.GET;
import javax.ws.rs.Path;
import javax.ws.rs.Produces;
import javax.ws.rs.QueryParam;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;

@Path("/tools")
@Produces(MediaType.APPLICATION_JSON)
public class ToolResource {
    private final GameTools gameTools;

    @Inject
    public ToolResource(GameTools gameTools) {
        this.gameTools = Preconditions.checkNotNull(gameTools);
    }

    @GET
    @Path("clean_games")
    public Response cleanOldGames(@QueryParam("maxAgeInHours") Long maxAgeInHours) {
        int gamesRemoved;
        if (maxAgeInHours == null) {
            gamesRemoved = gameTools.removeOldGames();
        } else {
            gamesRemoved = gameTools.removeOldGames(maxAgeInHours);
        }
        return Response.ok(ImmutableMap.of("removed", gamesRemoved)).build();
    }
}
